from scipy.spatial.transform import Rotation as R
q=np.array([-1.571,1.571,0,1.376,0,1.485,1.308]);
for signs in [(1,1,1),(1,-1,1)]:
 def fk(q):
  T=np.eye(4)
  for i in range(7):
   T[:3,:3]=T[:3,:3]@R.from_euler('z' if i%2==0 else 'y',q[i]*(signs[[1,3,5].index(i)] if i in [1,3,5] else 1)).as_matrix()
   if i in [0,2,4,6]:T[:3,3]+=T[:3,:3]@[0,0,{0:.36,2:.42,4:.4,6:.126}[i]]
  return T
 p=fk(q)[:3,3];print(signs,p)
 for j in [0,1,2,3,4,5]:
  q2=q.copy();q2[j]+=.01;print(j,(fk(q2)[:3,3]-p)/.01)
